import {downloadSchoolBook} from './features/book-library.mjs?v=phase1-books2';
import {schoolBooks} from './books/catalog.mjs?v=phase1-books';
import {videoView,bindVideo,videoAction,videoChange} from './features/interactive-video.mjs?v=phase1-books2';
import {plansView,planAction} from './features/preparation.mjs?v=curriculum1448';
import {bankView,bankAction,saveLessonQuestions,selectBank,importBank,bankGrade,setBankGrade} from './features/question-bank.mjs?v=phase1-books2';
import {assessmentView,assessmentAction,validAssessment} from './assessment.mjs?v=phase1-books2';
import {digit as n,escape as esc,kinds,validOutline,validLesson,calculationCheck,parsePages,safeImage,lessonQuestions} from './lesson-core.mjs';
const root=document.querySelector('#app'),$=id=>document.getElementById(id),cfg=window.SCHOOL_CONFIG||{};
let db,lessons=[],books=[],current=null,tab='library',index=0,shown=0,present=false,pen=false,token='',widget=null,busy=false,pdf=null,openedBook=null,previewPage=1,cropImage=null,cropBox=null,selectionStart=null;
const routeTabs={workspace:null,activities:'library',textbooks:'books',assessments:'papers',presentations:'editor',ai:'prepare','lesson-prep':'library',plans:'plans','question-bank':'bank',tests:'tests',worksheets:'worksheets',video:'video'};
const isWorkspace=()=>location.hash.slice(1) in routeTabs;
let generationTarget='prepare',generationDestination=null,paperMode='worksheet';
let metadata={subject:'الرياضيات',grade:'الرابع الابتدائي',title:'',count:10},status='';
const defaults=()=>({id:crypto.randomUUID(),version:3,title:'درس جديد',subject:metadata.subject,grade:metadata.grade,goals:['أحدد فكرة الدرس.'],slides:[newSlide('goals','أهداف الدرس'),newSlide('concept','تمهيد الدرس'),newSlide('example','مثال محلول'),newSlide('activity','نشاط'),newSlide('quiz','تقويم'),newSlide('summary','خلاصة الدرس')],sources:[],assets:[],outline:null,approved:false,sourceReviewed:false,theme:'garden',usage:[],updated:Date.now()});
function newSlide(kind='concept',title='شريحة جديدة'){return {kind,title,body:'',steps:[],page:0,imageIndex:-1,question:'',options:[],correct:-1,explanation:'',calculation:{a:-1,b:-1,result:-1}}}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('interactive-school-v3',1);r.onupgradeneeded=()=>{r.result.createObjectStore('lessons',{keyPath:'id'});r.result.createObjectStore('books',{keyPath:'id'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('تعذر فتح الحفظ المحلي'))})}
function transact(name,mode,fn){return new Promise((resolve,reject)=>{const t=db.transaction(name,mode),r=fn(t.objectStore(name));t.oncomplete=()=>resolve(r?.result);t.onerror=()=>reject(Error('تعذر الحفظ. صدّر الدرس وتحقق من مساحة المتصفح.'));t.onabort=t.onerror})}
const all=name=>transact(name,'readonly',s=>s.getAll());
async function refresh(){[lessons,books]=await Promise.all([all('lessons'),all('books')]);lessons.sort((a,b)=>b.updated-a.updated)}
async function save(){if(!current)return;if(current.assessment){current.assessments=current.assessments||{};current.assessments[current.assessment.type]=current.assessment;}current.updated=Date.now();await transact('lessons','readwrite',s=>s.put(current));await refresh()}
const field=(id,label,value='',extra='')=>`<label class="field" for="${id}"><span>${label}</span><input id="${id}" value="${esc(value)}" ${extra}></label>`;
const button=(text,action,cls='')=>`<button class="${cls}" data-ws="${action}">${text}</button>`;
function announce(message){status=message;if($('ws-status'))$('ws-status').textContent=message}
function pageImage(i,alt='صفحة من الكتاب'){return `<img class="page-thumb" src="${i}" alt="${alt}" data-big="1">`}
function navigation(){const titles={library:'تحضير الدروس',books:'الكتب الدراسية',sources:'مصدر الدرس',prepare:'إعداد طلب التوليد',outline:'المخطط والأهداف',editor:'العروض التفاعلية',activities:'أسئلة الدرس',papers:paperMode==='test'?'الاختبارات':'أوراق العمل',bank:'بنك الأسئلة',plans:'الخطط',video:'الفيديو التفاعلي'};return `<div class="ws-top"><div><div class="ws-kicker">${['books','library','sources','plans','outline'].includes(tab)?'التحضير':['papers','bank'].includes(tab)?'التقويم':'المحتوى'} / ${esc(titles[tab]||'الدرس')}</div><h1>${esc(titles[tab]||'الدرس')}</h1><p>${tab==='books'?'اربط كل كتاب بصفّه وفصله الدراسي.':tab==='library'?'دروسك المحفوظة، مفصولة حسب الصف.':tab==='papers'?'جهّز اختبارًا أو ورقة عمل من المصدر، ثم راجعها واطبعها.':tab==='plans'?'نظّم الخطة الأسبوعية وتوزيع المنهج.':tab==='bank'?'صنّف الأسئلة واستخدمها في أكثر من أداة.':tab==='prepare'?'حدد طلبك ليجهّز الموقع المحتوى من صفحات الكتاب.':'اعمل على الدرس المختار من المصدر إلى العرض.'}</p></div></div>${current&&!['library','books','bank','plans','video'].includes(tab)?`<details class="lesson-navigation"><summary>متابعة الدرس: ${esc(current.title)} • ${esc(current.grade)}</summary><nav class="ws-tabs" aria-label="خطوات الدرس">${[['sources','مصدر الدرس'],['prepare','طلب التوليد'],['editor','تحرير العرض'],['activities','أسئلة الدرس'],['papers','الطباعة'],['outline','خيارات المخطط']].map(([v,t])=>`<button data-tab="${v}" aria-pressed="${tab===v}">${t}</button>`).join('')}</nav></details>`:''}<div id="ws-status" role="status" class="ws-status">${esc(status||'الكتب والأعمال محفوظة في هذا المتصفح. التوليد المدفوع يتطلب موافقتك.')}</div>`}
window.selectWorkspaceGrade=grade=>{metadata.grade=grade;setBankGrade(grade);current=null;pdf=null;openedBook=null};
window.renderWorkspace=(wanted)=>{if(['library','books','editor'].includes(wanted)){generationTarget='prepare';generationDestination=null;}if(wanted&&wanted!==tab)status='';document.querySelectorAll('.portal-sidebar a').forEach(a=>{if(a.getAttribute('href')===location.hash)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(['tests','worksheets'].includes(wanted)){generationDestination=null;paperMode=wanted==='tests'?'test':'worksheet';generationTarget=paperMode;if(current){current.assessments=current.assessments||{};if(current.assessment)current.assessments[current.assessment.type]=current.assessment;current.assessment=current.assessments[paperMode]||{title:paperMode==='test'?'اختبار جديد':'ورقة عمل جديدة',type:paperMode,school:'',teacher:'',duration:30,questions:[]};}tab='papers';}else if(wanted)tab=wanted;root.classList.add('ws');if(db)draw()};
function draw(){if(!isWorkspace())return;cleanupWidget();if(present){root.innerHTML=`<div class="present-wrap">${stage()}<div class="present-nav">${button('→ السابق','prev','secondary')}<span>${n(index+1)} / ${n(current.slides.length)}</span>${button('التالي ←','next')}${current.slides[index].steps.length?button('اكشف الخطوة','reveal'):''}${button(pen?'إنهاء القلم':'القلم','pen','secondary')}${button('مسح الرسم','erase','secondary')}${button('إنهاء العرض','exit','secondary')}</div></div>`+dialogs();initInk();return}root.innerHTML=navigation()+({library:library,sources:sources,outline:outline,editor:editor,activities:activities,books:bookLibrary,prepare:prepare,bank:bankView,plans:plansView,video:videoView,papers:()=>current?assessmentView(current,lessons):requireLesson()}[tab]||library)()+dialogs();if(tab==='outline'||tab==='prepare')mountWidget();if(tab==='editor'&&current)initInk();bindCrop();if(tab==='video')bindVideo();}
function requireLesson(){return `<section class="ws-card"><h2>اختر الدرس الذي تريد العمل عليه</h2><p>يمكنك فتح درس محفوظ للصف ${esc(metadata.grade)} أو بدء طلب جديد من كتابه. غيّر الصف من تحضير الدروس.</p><div class="ws-grid">${lessons.filter(l=>l.grade===metadata.grade&&(tab==='papers'||l.artifact!=='assessment')).map(l=>`<article class="ws-card"><h3>${esc(l.title)}</h3><p>${esc(l.grade)}</p><button data-pick-lesson="${l.id}">اختيار هذا الدرس</button></article>`).join('')||'<p>لا توجد دروس محفوظة بعد.</p>'}</div>${button('طلب جديد من الكتاب','new')}${tab==='papers'?'<p class="ws-small">لطلب مستند تلقائيًا اختر الدرس ثم اضغط زر التوليد داخل الأداة.</p>':''}</section>`}
function library(){return `<section class="ws-card"><label class="field"><span>الصف</span><select id="library-grade"><option ${metadata.grade==='الرابع الابتدائي'?'selected':''}>الرابع الابتدائي</option><option ${metadata.grade==='السادس الابتدائي'?'selected':''}>السادس الابتدائي</option></select></label><div class="ws-actions">${button('حضّر درسًا من الكتاب','new')}${button('استيراد ملف درس','import','secondary')}<input id="import-lesson" type="file" accept=".json,application/json" hidden></div><p class="ws-small">الأعمال محفوظة في هذا المتصفح فقط. صدّر نسخة لحفظها خارج المتصفح أو نقلها إلى جهاز آخر. بيانات الأدوات القديمة محفوظة كما كانت.</p><div class="ws-grid">${lessons.filter(l=>l.grade===metadata.grade&&l.artifact!=='assessment').map(l=>`<article class="ws-card"><div class="ws-kicker">${esc(l.subject||'درس')} • ${esc(l.grade||'')}</div><h2>${esc(l.title)}</h2><p class="ws-small">${n(l.slides.length)} شرائح • ${n(l.sources?.length||0)} صفحات مصدر</p><button data-open="${l.id}">فتح الدرس</button> <button class="danger" data-delete="${l.id}">حذف</button></article>`).join('')||'<p>اختر كتاب الصف ثم صفحات الدرس، وسيجهّز الموقع المطلوب من مصدره.</p>'}</div></section>`}
function bookLibrary(){return `<section class="ws-card"><h2>الكتب المدرسية المعتمدة</h2><div class="ws-grid">${schoolBooks.map(b=>`<article class="ws-card official-book"><img src="${b.cover}" alt="غلاف ${esc(b.name)}" loading="lazy"><h3>${esc(b.name)}</h3><p>${n(b.pages)} صفحة • ${esc(b.edition)} • ${n(Math.round(b.bytes/1024/1024))} ميغابايت تقريبًا</p><button data-catalog-book="${b.id}">استخدم الكتاب لتحضير درس</button> <a href="${b.path}" target="_blank" rel="noopener">عرض PDF</a></article>`).join('')}</div><p class="ws-note">الكتابان المرفقان متاحان من الموقع. تُحمّل نسخة على جهازك عند اختيار الكتاب؛ لا يُرسل للذكاء الاصطناعي إلا صفحات الدرس التي تختارها وتوافق عليها.</p><h2>كتبي المضافة محليًا</h2><p>أضف كتاب الرابع وكتاب السادس، وحدد الفصل الدراسي. الكتب كاملة تبقى على جهازك؛ اختر صفحات الدرس مصدرًا للعمل.</p><div class="ws-grid"><label class="field"><span>صف الكتاب الجديد</span><select id="book-grade"><option ${metadata.grade==='الرابع الابتدائي'?'selected':''}>الرابع الابتدائي</option><option ${metadata.grade==='السادس الابتدائي'?'selected':''}>السادس الابتدائي</option></select></label><label class="field"><span>الفصل الدراسي</span><select id="book-term"><option>الفصل الأول</option><option>الفصل الثاني</option></select></label></div>${button('إرفاق كتاب PDF','book-upload')}<input id="pdf-file" type="file" accept="application/pdf,.pdf" hidden><div class="ws-grid">${books.map(b=>`<article class="ws-card"><h3>${esc(b.name)}</h3><p>${esc(b.grade||'الصف غير محدد')} • ${esc(b.term||'')} • ${n(b.pages)} صفحة</p><button data-book="${b.id}">اختيار الكتاب ومصدر الدرس</button></article>`).join('')||'<p>لم تضف كتبًا بعد. أضف الملفين مرة واحدة في هذا المتصفح.</p>'}</div><p class="ws-note">الكتاب هو مرجع المحتوى. لا ننشئ أسئلة موثقة بصفحة إلا من الدروس ذات المصدر المختار. الحفظ محلي؛ احتفظ بملفات PDF الأصلية.</p></section>`}
function sources(){if(!current)return requireLesson();return `<section class="ws-card"><h2>١. اختر مصدر الدرس</h2><p>الكتاب الكامل يبقى في متصفحك. نستخدم الصفحات التي تختارها فقط.</p><div class="ws-grid">${field('lesson-title','عنوان الدرس',current.title,'maxlength="180"')}${field('subject','المادة',current.subject,'maxlength="80"')}${field('grade','صف كتاب المصدر',current.grade,'readonly')}</div><div class="ws-actions">${button('حفظ بيانات الدرس','meta')}${button('إضافة كتاب PDF للمكتبة','book-upload','secondary')}${button('إضافة صور صفحات','images-upload','secondary')}<input id="pdf-file" type="file" accept="application/pdf,.pdf" hidden><input id="image-files" type="file" accept="image/png,image/jpeg,image/webp" multiple hidden></div><div class="ws-note">حد الكتاب ٢٠٠ ميغابايت. استخدم أحدث متصفح؛ إذا رفض الحفظ فصدّر دروسك ووفّر مساحة. رفع PDF لا يعني أن محتواه استُخرج أو روجع تلقائيًا.</div>${books.filter(b=>!b.grade||b.grade===current.grade).map(b=>`<div class="book-record"><strong>${esc(b.name)}</strong><p class="ws-small">${n(b.pages)} صفحة • محفوظ محليًا</p><button data-book="${b.id}">فتح الكتاب</button> <button class="danger" data-remove-book="${b.id}">حذف الكتاب المحلي</button></div>`).join('')}${pdf?`<div class="ws-card"><h3>${esc(openedBook?.name||'الكتاب')}</h3><div class="ws-grid">${field('page-numbers','صفحات ملف PDF المطلوبة',current.selection||'','placeholder="صفحات الدرس من ملفك"')}${field('page-offset','فرق الترقيم: صفحة PDF − صفحة الكتاب',current.pageOffset||0,'type="number" min="-1000" max="1000"')}</div><p class="ws-small">قد تختلف صفحة الملف عن الرقم المطبوع. عاين صفحة وتأكد من الفرق قبل الإضافة. نسمح حتى ٨ صفحات لكل درس.</p><div class="ws-actions">${button('معاينة صفحة','preview-pdf','secondary')}${button('إضافة الصفحات المختارة للدرس','select-pages')}</div><div id="pdf-preview"></div><details><summary>فهرس PDF إن كان مضمّنًا</summary><div id="pdf-outline">${esc(openedBook?.outline||'لا يوجد فهرس مضمّن؛ حدّد الصفحات يدويًا.')}</div></details></div>`:''}</section><section class="ws-card"><h2>٢. راجع صفحات الدرس وصوره</h2><div class="page-grid">${current.sources.map((s,i)=>`<article>${pageImage(s.image,'صفحة '+n(s.page))}<p class="ws-small">الكتاب: ${n(s.page)} • الملف: ${n(s.pdfPage||s.page)}</p><button data-crop="${i}">اقتطاع صورة أو مثال</button> <button class="danger" data-remove-source="${i}">إزالة</button></article>`).join('')}</div><p class="ws-small">القص محلي من الصورة الأصلية؛ لا يولّد صورًا بديلة. اضغط الصورة لمعاينتها، واقتطع صورًا للشرائح كي لا نعرض الصفحة كاملة في كل شريحة.</p><div class="asset-grid">${current.assets.map((a,i)=>`<div><img src="${a.image}" alt="${esc(a.name)}"><p class="ws-small">${n(i+1)}. ${esc(a.name)}</p></div>`).join('')}</div><label class="field" for="source-text"><span>النص المستخرج / ملاحظات المصدر (راجعه وصححه)</span><textarea id="source-text" maxlength="18000">${esc(current.sourceText||'')}</textarea></label><p class="ws-note">استخراج PDF قد يشوّه العربية والمعادلات. الصفحات المصوّرة تحتاج قراءة بصرية مدفوعة إذا اخترت استخدام الذكاء الاصطناعي؛ ويمكنك كتابة المحتوى والمخطط يدويًا دون تكلفة.</p><label class="ws-check"><input id="source-reviewed" type="checkbox" ${current.sourceReviewed?'checked':''}>راجعت الصفحات المختارة وترقيمها، وصححت النص أو سأعتمد الصور بوصفها المصدر.</label><div class="ws-actions">${button('اعتماد المصدر والانتقال للتجهيز التلقائي','save-source')}</div></section>`}
function prepare(){if(!current)return requireLesson();const targetName=generationDestination==='bank'?'أسئلة لبنك الأسئلة':generationTarget==='test'?'اختبار':generationTarget==='worksheet'?'ورقة عمل':'عرض الدرس';return `<section class="ws-card"><h2>ولّد ${targetName} من كتابك</h2><p><strong>${esc(current.grade)}</strong> • ${esc(current.bookName||'اختر كتاب المصدر أولًا')} • ${n(current.sources.length)} صفحات</p><p>يُعدّ الذكاء الاصطناعي المحتوى من الصفحات المختارة، دون إدخال الأسئلة أو الشرائح يدويًا. راجع النتيجة قبل استخدامها.</p>${field('auto-requirements','ما المطلوب؟ (المستوى، الأنواع، الزمن، مجموع الدرجات…)',current.requirements||'','maxlength="2000" placeholder="مثال: اختبار فتري ٢٠ درجة، ٣٠ دقيقة، اختيار من متعدد وأسئلة حل"')}<label class="field"><span>عدد الشرائح أو الأسئلة</span><select id="ai-count">${[4,6,8,10,12,16,18].map(v=>`<option value="${v}" ${v===8?'selected':''}>${n(v)}</option>`).join('')}</select></label><label class="ws-check"><input id="send-images" type="checkbox" checked>إرسال صور الصفحات لقراءة الأمثلة والمعطيات.</label><div id="v3-verification"></div><label class="ws-check"><input id="paid-consent" type="checkbox">أوافق على إرسال الصفحات المحددة إلى OpenAI واستهلاك رصيد API لهذا الطلب.</label><div class="ws-actions">${button('ولّد '+targetName,'ai-'+generationTarget)}</div><p class="ws-note">هذا طلب مدفوع مستقل. لا تحتاج إنشاء المحتوى يدويًا. الأوراق والاختبارات تُفتح بعد التوليد في مصمم الطباعة، والعرض في الشرائح. لا نستخدم درسًا تجريبيًا بديلًا عن مصدر الكتاب.</p></section>`}
function outline(){if(!current)return requireLesson();const o=current.outline||{title:current.title,goals:current.goals,sections:current.slides.map(s=>({kind:s.kind,title:s.title,page:s.page,notes:s.body}))};return `<section class="ws-card"><h2>٣. مخطط يسبق التوليد</h2><p>الأهداف في البداية. عدّل المخطط واعتمده قبل إنشاء الشرائح.</p>${field('outline-title','عنوان المخطط',o.title,'maxlength="180"')}<label class="field" for="outline-goals"><span>الأهداف • هدف في كل سطر (حتى ٦)</span><textarea id="outline-goals" maxlength="1400">${esc(o.goals.join('\n'))}</textarea></label><div id="outline-sections">${o.sections.map((s,i)=>`<div class="ws-card"><div class="ws-grid">${field('section-title-'+i,'عنوان الشريحة '+n(i+1),s.title,'maxlength="160"')}<label class="field"><span>نوعها</span><select id="section-kind-${i}">${kindOptions(s.kind)}</select></label>${field('section-page-'+i,'صفحة الكتاب (٠ للإضافات)',s.page,'type="number" min="0"')}</div><label class="field"><span>الفكرة / ملاحظات</span><textarea id="section-notes-${i}" maxlength="500">${esc(s.notes)}</textarea></label></div>`).join('')}</div><div class="ws-actions">${button('إضافة بند للمخطط','outline-add','secondary')}${button('حفظ المخطط','outline-save','secondary')}${button('اعتماد المخطط وبناء شرائح يدوية • دون API','outline-manual')}</div></section><section class="ws-card"><h2>الذكاء الاصطناعي • اختياري ومدفوع</h2><p class="ws-small">كل زر يرسل طلبًا مستقلًا إلى OpenAI عبر الخادم. لا تُرسل ملفات الكتاب الكاملة؛ الصفحات المختارة والنص والمخطط فقط. الصور تُحسب ضمن الاستخدام. لا يوجد سعر ثابت أو وعد بتكلفة محددة؛ تُسجّل أعداد الرموز بعد الاستجابة، وتراجع التكلفة المالية في حساب المزود.</p><label class="field"><span>عدد الشرائح للمخطط الآلي</span><select id="ai-count">${[6,8,10,12].map(x=>`<option value="${x}" ${x===metadata.count?'selected':''}>${n(x)}</option>`).join('')}</select></label><label class="ws-check"><input type="checkbox" id="send-images" checked>إرفاق صور الصفحات المختارة لقراءة أمثلة الكتاب ومعادلاته (مدفوع). عند إلغاء الخيار يُرسل النص فقط.</label><div class="ws-note">المخطط والشرائح مسودات تحتاج مراجعتك. قراءة الصور لا تضمن صحة كل كلمة أو معادلة. التحقق البرمجي يغطي عمليات الضرب المرفقة فقط.</div><div id="v3-verification"></div><label class="ws-check"><input type="checkbox" id="paid-consent">أوافق على إرسال المصدر المحدد إلى OpenAI واستهلاك رصيد API لهذا الطلب.</label><div class="ws-actions">${button('توليد مخطط مدفوع','ai-outline')}${button('اعتماد المخطط وتوليد الشرائح • مدفوع','ai-lesson')}</div><p class="ws-small">${cfg.apiUrl?'خدمة التوليد مربوطة.':'أضف رابط الخدمة في config.js لتفعيل التوليد.'}</p></section>`}
const kindNames={cover:'عنوان',goals:'أهداف',concept:'شرح بصري',example:'مثال وخطوات',activity:'نشاط',quiz:'تقويم',summary:'خلاصة'};
const kindOptions=k=>kinds.map(v=>`<option value="${v}" ${v===k?'selected':''}>${kindNames[v]}</option>`).join('');
function collectOutline(){const base=current.outline||{sections:current.slides};const o={title:$('outline-title').value.trim(),goals:$('outline-goals').value.split('\n').map(x=>x.trim()).filter(Boolean),sections:base.sections.map((_,i)=>({title:$('section-title-'+i).value.trim(),kind:$('section-kind-'+i).value,page:Number($('section-page-'+i).value),notes:$('section-notes-'+i).value.trim()}))};if(!validOutline(o))throw Error('المخطط يحتاج ٤–١٨ بندًا و١–٦ أهداف، مع مراعاة حدود النص.');return o}
function normalizeGoals(){const goals={...newSlide('goals','أهداف الدرس'),body:current.goals.map((g,i)=>n(i+1)+'. '+g).join('\n')};const others=current.slides.filter(s=>s.kind!=='goals');if(others[0]?.kind==='cover')others.splice(1,0,goals);else others.unshift(goals);current.slides=others;}
function stage(){const s=current.slides[index],asset=current.assets[s.imageIndex],src=asset?.image||current.sources.find(p=>p.page===s.page)?.image;const q=s.question?`<h2>${esc(s.question)}</h2><div class="quiz-options">${s.options.map((o,i)=>`<button data-option="${i}">${esc(o)}</button>`).join('')}</div><p id="v3-feedback" aria-live="polite"></p>`:'';const content=s.kind==='goals'?`<ul>${current.goals.map(g=>`<li>${esc(g)}</li>`).join('')}</ul>`:`${s.body?`<p>${esc(s.body)}</p>`:''}${s.steps.map((t,i)=>`<div class="step-line ${i>=shown?'pending':''}">${esc(t)}</div>`).join('')}${q}`;return `<article id="v3-stage" class="lesson-stage ${s.kind==='cover'?'cover':''} ${current.theme==='night'?'night':''}"><span class="source-tag">${kindNames[s.kind]}</span><h1>${esc(s.title)}</h1>${src?`<div class="slide-columns"><div>${content}</div><img class="source-image" data-big="1" src="${src}" alt="${esc(asset?.name||'صفحة المصدر '+n(s.page))}"></div>`:content}${s.kind==='cover'?'<div class="cover-mark">✦</div>':''}<div class="source-foot">${s.page?'المصدر: '+esc(current.bookName||'الكتاب المرفق')+' • صفحة '+n(s.page):'إضافة تعليمية • راجعها قبل العرض'}${asset?' • صورة أصلية مقتطعة من الكتاب':''}</div><canvas id="v3-ink" aria-label="القلم"></canvas></article>`}
function editor(){if(!current)return requireLesson();index=Math.min(index,current.slides.length-1);const s=current.slides[index],check=calculationCheck(s);return `<div class="ws-layout"><aside class="ws-card ws-sidebar"><h2>${esc(current.title)}</h2><div class="slide-list">${current.slides.map((s,i)=>`<button class="${i===index?'current':''}" data-slide="${i}">${n(i+1)}. ${esc(s.title)}</button>`).join('')}</div><div class="ws-actions">${button('إضافة شريحة','slide-add','secondary')}${button('حذف','slide-delete','danger')}</div>${button('حفظ الدرس','save')}<div class="ws-actions"><button data-generate="prepare">ولّد عرضًا من المصدر</button><button data-save-bank="slides">حفظ أسئلة العرض في البنك</button>${button('عرض الحصة','present')}${button('تصدير نسخة JSON','export','secondary')}${button('تنزيل عرض يعمل دون إنترنت','offline','secondary')}</div><label class="field"><span>الهوية البصرية</span><select id="lesson-theme"><option value="garden" ${current.theme!=='night'?'selected':''}>حديقة • فاتح</option><option value="night" ${current.theme==='night'?'selected':''}>ليل • داكن</option></select></label></aside><section><div class="ws-actions">${button('→ السابق','prev','secondary')}<span>${n(index+1)} / ${n(current.slides.length)}</span>${button('التالي ←','next','secondary')}${s.steps.length?button('اكشف الخطوة','reveal'):''}${button(pen?'إنهاء القلم':'القلم','pen','secondary')}${button('مسح الرسم','erase','secondary')}</div>${stage()}<section class="ws-card"><h2>تحرير الشريحة</h2>${field('slide-title','العنوان',s.title,'maxlength="160"')}<div class="ws-grid"><label class="field"><span>القالب</span><select id="slide-kind">${kindOptions(s.kind)}</select></label>${field('slide-page','صفحة المصدر',s.page,'type="number" min="0"')}<label class="field"><span>صورة أصلية للعرض</span><select id="slide-image"><option value="-1">صفحة المصدر كاملة / دون صورة</option>${current.assets.map((a,i)=>`<option value="${i}" ${i===s.imageIndex?'selected':''}>${n(i+1)}. ${esc(a.name)}</option>`).join('')}</select></label></div><label class="field"><span>النص • حد أقصى ٦٠ كلمة و١٠٠٠ حرف</span><textarea id="slide-body" maxlength="1000">${esc(s.kind==='goals'?current.goals.join('\n'):s.body)}</textarea></label><label class="field"><span>خطوات تظهر بالنقر • خطوة في كل سطر (حتى ٦)</span><textarea id="slide-steps" maxlength="1800">${esc(s.steps.join('\n'))}</textarea></label>${field('slide-question','السؤال',s.question,'maxlength="500"')}<label class="field"><span>٤ خيارات • خيار في كل سطر، أو اتركها فارغة</span><textarea id="slide-options">${esc(s.options.join('\n'))}</textarea></label><label class="field"><span>الإجابة الصحيحة</span><select id="slide-correct">${[0,1,2,3].map(i=>`<option value="${i}" ${i===s.correct?'selected':''}>${n(i+1)}</option>`).join('')}</select></label><label class="field"><span>تفسير الإجابة</span><textarea id="slide-explanation" maxlength="500">${esc(s.explanation)}</textarea></label><details><summary>التحقق من عملية ضرب مرفقة</summary><p class="ws-small">يتحقق من هذه العملية فقط، ولا يفحص كل معادلة في النص أو الصورة. اترك القيم −١ عند عدم وجود عملية.</p><div class="ws-grid">${field('calc-a','العامل الأول',s.calculation.a,'type="number"')}${field('calc-b','العامل الثاني',s.calculation.b,'type="number"')}${field('calc-r','الناتج',s.calculation.result,'type="number"')}</div></details><p class="ws-small ${check.state==='error'?'ws-error':check.state==='verified'?'ws-success':'muted'}">${esc(check.text)}</p><div class="ws-actions">${button('حفظ ومعاينة','slide-save')}${button('نقل للأعلى','slide-up','secondary')}${button('نقل للأسفل','slide-down','secondary')}</div></section></section></div>`}
function commitSlide(){if(!current||!$('slide-title'))return;const options=$('slide-options').value.split('\n').map(v=>v.trim()).filter(Boolean);if(options.length!==0&&options.length!==4)throw Error('الخيارات إما أربعة أو فارغة.');const s={...current.slides[index],title:$('slide-title').value,kind:$('slide-kind').value,page:Number($('slide-page').value),imageIndex:Number($('slide-image').value),body:$('slide-body').value,steps:$('slide-steps').value.split('\n').filter(v=>v.trim()),question:$('slide-question').value,options,correct:options.length?Number($('slide-correct').value):-1,explanation:$('slide-explanation').value,calculation:{a:Number($('calc-a').value),b:Number($('calc-b').value),result:Number($('calc-r').value)}};if(!validLesson({...current,slides:[s]}))throw Error('تحقق من طول النص (حتى ٦٠ كلمة) والخطوات والقيم العددية.');if(s.kind==='goals'){const goals=s.body.split('\n').map(x=>x.trim()).filter(Boolean);if(!goals.length||goals.length>6||goals.some(g=>g.length>220))throw Error('اكتب من هدف إلى ستة أهداف قصيرة.');current.goals=goals;}current.slides[index]=s;current.theme=$('lesson-theme').value;}
function activities(){if(!current)return requireLesson();const qs=lessonQuestions(current);return `<section class="ws-card"><h2>أنشطة الدرس نفسه</h2><p>هذه الأسئلة مأخوذة من الشرائح، وتظهر أيضًا في العرض. غيّر السؤال مرة واحدة في المحرر.</p>${qs.length?qs.map((q,i)=>`<div class="ws-card"><h3>${n(i+1)}. ${esc(q.q)}</h3><div class="ws-grid">${q.a.map((a,j)=>`<button data-practice="${i},${j}" class="secondary">${esc(a)}</button>`).join('')}</div><p id="practice-${i}" aria-live="polite"></p></div>`).join(''):'<p>لا توجد أسئلة اختيار من متعدد؛ أضفها من محرر الشرائح.</p>'}<div class="ws-note">يمكن نسخ الدرس إلى أدوات الإصدار السابق. يتطلب ذلك تأكيد استبدال محتوى تلك الأدوات؛ التصدير الاحتياطي متاح من الرئيسية قبل النسخ.</div><div class="ws-actions">${button('نسخ العرض والكتاب والأسئلة إلى الأدوات الأربع','bridge')}${button('تصدير الدرس','export','secondary')}</div><h3>سجل الاستخدام لهذا الدرس</h3><p class="ws-small">الرموز وليست الدولارات. التكلفة المالية متاحة في حساب OpenAI.</p><table><thead><tr><th>الطلب</th><th>النموذج</th><th>إدخال</th><th>إخراج</th></tr></thead><tbody>${(current.usage||[]).map(u=>`<tr><td>${({outline:'مخطط',lesson:'شرائح',prepare:'درس كامل',worksheet:'ورقة عمل',test:'اختبار فتري'}[u.stage]||u.stage)}</td><td>${esc(u.model||'')}</td><td>${n(u.input||0)}</td><td>${n(u.output||0)}</td></tr>`).join('')}</tbody></table></section>`}
function dialogs(){return `<dialog id="image-dialog"><button data-ws="close-image">إغلاق ×</button><img id="big-image" alt="معاينة صورة المصدر"></dialog><dialog id="crop-dialog"><h2>اقتطع الصورة الأصلية</h2><p class="ws-small">اسحب لتحديد المستطيل. لا نغيّر محتوى الصورة.</p><div class="crop-frame"><canvas id="crop-canvas"></canvas></div>${field('crop-name','اسم الصورة','صورة من الكتاب','maxlength="100"')}<div class="ws-actions">${button('حفظ الصورة المحددة','crop-save')}${button('إلغاء','crop-cancel','secondary')}</div><p id="crop-status" role="status"></p></dialog>`}
function cleanupWidget(){if(widget!==null&&window.turnstile){try{window.turnstile.remove(widget)}catch{}}widget=null;token=''}
function mountWidget(){if(!cfg.turnstileSiteKey)return;if(window.turnstile){widget=window.turnstile.render('#v3-verification',{sitekey:cfg.turnstileSiteKey,action:'generate',callback:t=>token=t,'expired-callback':()=>token='','error-callback':()=>token=''});return}let script=$('turnstileScript');if(!script){script=document.createElement('script');script.id='turnstileScript';script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';document.head.append(script)}script.addEventListener('load',()=>{if($('v3-verification'))mountWidget()},{once:true})}
async function loadPDF(bytes){const lib=await import('./vendor/pdf.mjs');lib.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;return lib.getDocument({data:new Uint8Array(bytes),cMapUrl:new URL('./vendor/cmaps/',import.meta.url).href,cMapPacked:true,standardFontDataUrl:new URL('./vendor/standard_fonts/',import.meta.url).href,wasmUrl:new URL('./vendor/wasm/',import.meta.url).href,isEvalSupported:false}).promise}
async function useBook(book){pdf=await loadPDF(await book.blob.arrayBuffer());openedBook=book;if(!current||tab==='books'||(book.grade&&current.grade!==book.grade)){current=defaults();current.title='درس من '+book.name;}if(book.grade)current.grade=book.grade;current.bookId=book.id;metadata.grade=current.grade;setBankGrade(current.grade);tab='sources';await save();draw();}
async function renderPage(pageNumber,width=1200){const p=await pdf.getPage(pageNumber),base=p.getViewport({scale:1}),v=p.getViewport({scale:width/base.width}),c=document.createElement('canvas');c.width=Math.ceil(v.width);c.height=Math.ceil(v.height);await p.render({canvasContext:c.getContext('2d'),viewport:v}).promise;const text=await p.getTextContent();return {image:c.toDataURL('image/jpeg',.82),text:text.items.map(t=>t.str+(t.hasEOL?'\n':' ')).join('')};}
async function imageData(file){if(!/^image\/(png|jpeg|webp)$/.test(file.type)||file.size>15000000)throw Error('اختر صورة PNG أو JPEG أو WebP أقل من ١٥ ميغابايت.');const bitmap=await createImageBitmap(file),c=document.createElement('canvas'),scale=Math.min(1,1400/Math.max(bitmap.width,bitmap.height));c.width=Math.round(bitmap.width*scale);c.height=Math.round(bitmap.height*scale);c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();return c.toDataURL('image/jpeg',.85)}
async function beginCrop(i){cropImage=new Image();cropImage.src=current.sources[i].image;await cropImage.decode();cropImage.sourcePage=current.sources[i].page;cropBox=null;$('crop-dialog').showModal();paintCrop()}
function paintCrop(){if(!cropImage||!$('crop-canvas'))return;const c=$('crop-canvas'),scale=Math.min(1,760/cropImage.width);c.width=Math.round(cropImage.width*scale);c.height=Math.round(cropImage.height*scale);const x=c.getContext('2d');x.drawImage(cropImage,0,0,c.width,c.height);if(cropBox){x.strokeStyle='#e24448';x.lineWidth=3;x.strokeRect(cropBox.x,cropBox.y,cropBox.w,cropBox.h)}}
function bindCrop(){const c=$('crop-canvas');if(!c)return;const point=e=>{const r=c.getBoundingClientRect();return {x:Math.max(0,Math.min(c.width,(e.clientX-r.left)*c.width/r.width)),y:Math.max(0,Math.min(c.height,(e.clientY-r.top)*c.height/r.height))}};c.onpointerdown=e=>{selectionStart=point(e);c.setPointerCapture(e.pointerId)};c.onpointermove=e=>{if(!selectionStart)return;const p=point(e);cropBox={x:Math.min(p.x,selectionStart.x),y:Math.min(p.y,selectionStart.y),w:Math.abs(p.x-selectionStart.x),h:Math.abs(p.y-selectionStart.y)};paintCrop()};c.onpointerup=()=>{selectionStart=null;if(cropBox)$('crop-status').textContent='تم تحديد المنطقة. اضغط حفظ.'};c.onpointercancel=()=>selectionStart=null}
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
async function exportOffline(){commitSlide();await save();const {offlineHTML}=await import('./offline.mjs');const oldIndex=index,oldShown=shown;const pages=current.slides.map((s,i)=>{index=i;shown=0;return stage().replace(/<canvas[^>]*><\/canvas>/,'')});index=oldIndex;shown=oldShown;download(offlineHTML(current,pages),'lesson-offline.html','text/html;charset=utf-8');announce('تم تنزيل عرض مستقل بصور الكتاب؛ افتحه في متصفح دون إنترنت.');}
